// Normalize Ironclad records and Docusign agreements into one contract shape,
// then compute the notice deadline that actually governs the decision.
//
// The date that matters is NOT the expiration date. It is the last day you can
// serve notice without the term rolling. Everything downstream keys off
// notice_deadline, never expiration_date.

const DEFAULT_NOTICE_DAYS = 90;      // conservative when the paper is silent
const TIERS = [90, 60, 30, 7];       // days before notice_deadline that trigger a nudge
const RADAR_HORIZON_DAYS = 90;       // ignore anything further out than the widest tier

// Display names of the Ironclad record fields holding renewal data. Edit these
// to match your instance; the schema node resolves them to field IDs.
const RENEWAL_FIELD_NAMES = {
  expiration: 'Expiration Date',
  noticeDays: 'Notice Period (Days)',
  renewalType: 'Renewal Type',
  annualValue: 'Annual Contract Value',
  owner: 'Business Owner Email',
};

const schemaResp = $('Ironclad — Record Schema').first().json;
const schemaFields = schemaResp.list || schemaResp.fields || [];

// Map display name -> field id. Fail loudly rather than silently defaulting:
// a missing notice-period field would make every contract look safe.
const fieldId = {};
for (const [key, displayName] of Object.entries(RENEWAL_FIELD_NAMES)) {
  const match = schemaFields.find((f) => (f.name || f.displayName) === displayName);
  if (!match && (key === 'expiration' || key === 'noticeDays')) {
    throw new Error(
      `schema_field_missing: no Ironclad record field named "${displayName}". ` +
      'Fix RENEWAL_FIELD_NAMES in this node to match your instance before enabling the cron.'
    );
  }
  if (match) fieldId[key] = match.id || match.fieldId;
}

// Calendar-date helpers. All math is on UTC date boundaries — a notice deadline
// is a legal date, not an instant, and DST must not be able to move it.
const toUtcDate = (v) => {
  if (!v) return null;
  const d = new Date(String(v).slice(0, 10) + 'T00:00:00Z');
  return Number.isNaN(d.getTime()) ? null : d;
};
const addDays = (d, n) => new Date(d.getTime() + n * 86400000);
const daysBetween = (a, b) => Math.round((b.getTime() - a.getTime()) / 86400000);
const iso = (d) => d.toISOString().slice(0, 10);

const today = toUtcDate(new Date().toISOString());
const out = [];
const dropped = [];

for (const item of $input.all()) {
  const raw = item.json;
  let c;

  if (raw.properties || raw.recordType) {
    // ---- Ironclad record ----
    const p = raw.properties || {};
    const val = (key) => {
      const f = fieldId[key] && p[fieldId[key]];
      return f && typeof f === 'object' ? f.value : f;
    };
    c = {
      contract_id: `ironclad:${raw.id}`,
      source: 'ironclad',
      title: raw.name || raw.type || 'Untitled record',
      counterparty: val('counterparty') || raw.counterpartyName || null,
      expiration_date: val('expiration'),
      notice_days: val('noticeDays'),
      renewal_type: val('renewalType'),
      annual_value_cents: Math.round(Number(val('annualValue') || 0) * 100) || null,
      owner_email: val('owner') || null,
      deep_link: `https://ironcladapp.com/records/${raw.id}`,
    };
  } else {
    // ---- Docusign agreement (Iris-extracted provisions) ----
    const pr = raw.provisions || {};
    // Docusign gives the notice DATE directly; derive days so both sources share a shape.
    const exp = toUtcDate(pr.expiration_date);
    const noticeDate = toUtcDate(pr.renewal_notice_date);
    c = {
      contract_id: `docusign:${raw.id}`,
      source: 'docusign',
      title: raw.file_name || raw.type || 'Untitled agreement',
      counterparty: (raw.parties || []).map((x) => x.name_in_agreement).filter(Boolean).join(', ') || null,
      expiration_date: pr.expiration_date || null,
      notice_days: exp && noticeDate ? daysBetween(noticeDate, exp) : null,
      renewal_type: pr.renewal_type || null,
      annual_value_cents: Math.round(Number(pr.total_agreement_value || 0) * 100) || null,
      owner_email: null,
      deep_link: `https://apps.docusign.com/navigator/agreements/${raw.id}`,
    };
  }

  const expiration = toUtcDate(c.expiration_date);
  if (!expiration) {
    dropped.push({ contract_id: c.contract_id, reason: 'no_expiration_date' });
    continue;
  }

  // A null notice period is the single most dangerous value in this flow.
  // Defaulting it to 0 would mark the contract safe until the day it renews.
  // Default to the conservative end and label the assumption so the Slack card
  // tells the reader the date is not from the paper.
  let noticeDays = Number(c.notice_days);
  let noticeSource = 'contract';
  if (!Number.isFinite(noticeDays) || noticeDays < 0) {
    noticeDays = DEFAULT_NOTICE_DAYS;
    noticeSource = 'assumed';
  }

  const noticeDeadline = addDays(expiration, -noticeDays);
  const daysToDeadline = daysBetween(today, noticeDeadline);

  // Widest tier that this contract has already reached. Past the deadline is its own tier.
  let tier = null;
  if (daysToDeadline < 0) tier = 'passed';
  else tier = TIERS.filter((t) => daysToDeadline <= t).sort((a, b) => a - b)[0] ?? null;

  if (tier === null || daysToDeadline > RADAR_HORIZON_DAYS) continue;

  out.push({
    json: {
      ...c,
      notice_days: noticeDays,
      notice_source: noticeSource,
      expiration_date: iso(expiration),
      notice_deadline: iso(noticeDeadline),
      days_to_deadline: daysToDeadline,
      tier: String(tier),
      run_date: iso(today),
    },
  });
}

if (dropped.length) {
  console.warn(`Dropped ${dropped.length} contract(s) with no expiration date`, dropped.slice(0, 20));
}

return out;

// Suppress contracts already nudged at their current tier. Without this the flow
// re-posts every in-window contract every weekday, the channel gets muted, and
// the deadline is missed anyway — the exact failure the radar exists to prevent.

const state = new Map();
for (const row of $('Load Radar State').all()) {
  if (row.json && row.json.contract_id) {
    state.set(row.json.contract_id, String(row.json.last_tier_notified ?? ''));
  }
}

return $input.all().filter((item) => {
  const prev = state.get(item.json.contract_id);
  return prev !== item.json.tier;
});

// Compute the recommendation deterministically from spend and usage, then treat
// the model's answer as advisory. The model writes the brief; arithmetic decides
// the route. This is what stops a confidently-worded brief from driving a
// terminate on a contract whose usage data never loaded.

const LOW_UTILIZATION = 0.40;        // below this, the seats are not being used
const SOFT_UTILIZATION = 0.70;       // below this, there is a downsize argument
const UPLIFT_RENEGOTIATE = 0.10;     // quoted increase above this is worth pushing back on
const ESCALATION_VALUE_CENTS = 5000000; // $50,000/yr and up goes to legal, not just the owner

const contract = $('New Tier Only').item.json;
const ctx = $('Load Spend + Usage').item.json || {};

const licensed = Number(ctx.licensed_seats);
const active = Number(ctx.active_seats_30d);
const lastTerm = Number(ctx.last_term_annual_cents);
const quoted = Number(ctx.quoted_renewal_annual_cents);

const utilization = Number.isFinite(licensed) && licensed > 0 && Number.isFinite(active)
  ? active / licensed
  : null;
const uplift = Number.isFinite(lastTerm) && lastTerm > 0 && Number.isFinite(quoted)
  ? (quoted - lastTerm) / lastTerm
  : null;

const contextComplete = utilization !== null && uplift !== null;

let deterministic;
if (utilization !== null && utilization < LOW_UTILIZATION) deterministic = 'terminate';
else if ((utilization !== null && utilization < SOFT_UTILIZATION) || (uplift !== null && uplift > UPLIFT_RENEGOTIATE)) deterministic = 'renegotiate';
else if (contextComplete) deterministic = 'renew';
else deterministic = 'renegotiate'; // no data is not a reason to sign the same paper again

// Parse the model brief. A malformed or missing body must degrade to the
// deterministic path, never abort the contract.
let brief = null;
let briefError = null;
try {
  const body = $json.content;
  const text = Array.isArray(body)
    ? body.filter((b) => b.type === 'text').map((b) => b.text).join('')
    : null;
  if (!text) throw new Error('no_text_block');
  brief = JSON.parse(text.trim().replace(/^```(?:json)?/, '').replace(/```$/, '').trim());
} catch (e) {
  briefError = e.message;
}

const modelRec = brief && brief.recommendation ? brief.recommendation : null;
const agrees = modelRec === deterministic;

const escalate =
  (Number(contract.annual_value_cents) || 0) >= ESCALATION_VALUE_CENTS ||
  contract.tier === '7' ||
  contract.tier === 'passed' ||
  contract.notice_source === 'assumed' ||
  !contract.renewal_type ||
  !agrees;

return {
  json: {
    ...contract,
    utilization,
    uplift,
    context_complete: contextComplete,
    recommendation: deterministic,
    model_recommendation: modelRec,
    model_agrees: agrees,
    confidence: brief && Number.isFinite(brief.confidence) ? brief.confidence : null,
    rationale: brief ? brief.rationale : 'Model brief unavailable — deterministic recommendation only.',
    leverage: brief && Array.isArray(brief.leverage) ? brief.leverage.slice(0, 3) : [],
    missing_data: brief && Array.isArray(brief.missing_data) ? brief.missing_data : [],
    brief_error: briefError,
    route: escalate ? 'legal_escalation' : 'owner_nudge',
  },
};

