={{ JSON.stringify([
  { type: 'header', text: { type: 'plain_text', text: `Notice deadline in ${$json.days_to_deadline} days — ${$json.counterparty || $json.title}` } },
  { type: 'section', fields: [
    { type: 'mrkdwn', text: `*Notice deadline*\n${$json.notice_deadline}${$json.notice_source === 'assumed' ? ' :warning: _assumed, not on file_' : ''}` },
    { type: 'mrkdwn', text: `*Expires*\n${$json.expiration_date}` },
    { type: 'mrkdwn', text: `*Renewal type*\n${$json.renewal_type || ':warning: unknown'}` },
    { type: 'mrkdwn', text: `*Annual value*\n${$json.annual_value_cents ? '$' + ($json.annual_value_cents / 100).toLocaleString() : 'not on file'}` },
    { type: 'mrkdwn', text: `*Seat utilization*\n${$json.utilization !== null ? Math.round($json.utilization * 100) + '%' : 'no usage data'}` },
    { type: 'mrkdwn', text: `*Quoted change*\n${$json.uplift !== null ? (($json.uplift > 0 ? '+' : '') + Math.round($json.uplift * 100) + '%') : 'no quote on file'}` }
  ] },
  { type: 'section', text: { type: 'mrkdwn', text: `*Recommendation: ${$json.recommendation.toUpperCase()}*\n${$json.rationale}` } },
  ...($json.leverage.length ? [{ type: 'section', text: { type: 'mrkdwn', text: '*Leverage*\n' + $json.leverage.map((l) => '• ' + l).join('\n') } }] : []),
  ...(!$json.model_agrees ? [{ type: 'context', elements: [{ type: 'mrkdwn', text: `:warning: Model recommended *${$json.model_recommendation || 'nothing parseable'}*; rules recommended *${$json.recommendation}*. Human decides.` }] }] : []),
  ...($json.missing_data.length ? [{ type: 'context', elements: [{ type: 'mrkdwn', text: 'Missing data: ' + $json.missing_data.join(', ') }] }] : []),
  { type: 'actions', elements: [{ type: 'button', text: { type: 'plain_text', text: 'Open contract' }, url: $json.deep_link }] }
]) }}

